cat > cli.go <<'EOF'
package main

import (
    "fmt"
    "os"
    "strconv"
    "strings"
)

const helpText = `
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
`

type options struct {
    Query, RCFile, InitialFilter, Prompt, Layout, OnCancel, Prefix, Exec, Height string
    Help, Version, Null, Select1, Exit0, SelectAll, PrintQuery, ANSI bool
    BufferSize, InitialIndex int
    Files []string
}
var flagKind = map[string]byte{
    "help":'b', "query":'s', "rcfile":'s', "version":'b', "buffer-size":'i', "null":'b',
    "initial-index":'i', "initial-filter":'s', "prompt":'s', "layout":'s', "select-1":'b', "exit-0":'b',
    "select-all":'b', "on-cancel":'s', "selection-prefix":'s', "exec":'s', "print-query":'b', "ansi":'b', "height":'s',
}
func flagLabel(name string) string {
    switch name {case "help":return "-h, --help";case "buffer-size":return "-b, --buffer-size"}
    return "--"+name
}
func parseOptions(args []string) (options,error) {
    var o options
    set:=func(name,v string,n int){
        switch name {
        case "help":o.Help=true;case "version":o.Version=true;case "query":o.Query=v
        case "rcfile":o.RCFile=v;case "buffer-size":o.BufferSize=n;case "null":o.Null=true
        case "initial-index":o.InitialIndex=n;case "initial-filter":o.InitialFilter=v
        case "prompt":o.Prompt=v;case "layout":o.Layout=v;case "select-1":o.Select1=true
        case "exit-0":o.Exit0=true;case "select-all":o.SelectAll=true;case "on-cancel":o.OnCancel=v
        case "selection-prefix":o.Prefix=v;case "exec":o.Exec=v;case "print-query":o.PrintQuery=true
        case "ansi":o.ANSI=true;case "height":o.Height=v
        }
    }
    flagErr:=func(msg string)(options,error){
        fmt.Fprintln(os.Stderr,msg)
        fmt.Fprint(os.Stderr,helpText)
        // The command-line parser formats the message a second time.
        msg=fmt.Sprintf(msg)
        return o,fmt.Errorf("failed to parse command line options: invalid command line options: %s",msg)
    }
    for i:=0;i<len(args);i++ {
        a:=args[i]
        if !strings.HasPrefix(a,"-") || a=="-" || a=="--" { o.Files=append(o.Files,a);continue }
        names:=[]string{}
        value:="";hasValue:=false
        if strings.HasPrefix(a,"--") {
            name:=a[2:]
            if p:=strings.IndexByte(name,'=');p>=0 {value=name[p+1:];name=name[:p];hasValue=true}
            names=append(names,name)
        } else {
            s:=a[1:]
            if len(s)>1 && s[0]=='b' {names=[]string{"buffer-size"};value=strings.TrimPrefix(s[1:],"=");hasValue=true} else {
                for _,r:=range s {
                    switch r {case 'h':names=append(names,"help");case 'b':names=append(names,"buffer-size");default:names=append(names,string(r))}
                }
            }
        }
        for _,name:=range names {
            kind,ok:=flagKind[name]
            if !ok {return flagErr(fmt.Sprintf("unknown flag `%s'",name))}
            label:=flagLabel(name)
            if kind=='b' {
                if hasValue {return flagErr(fmt.Sprintf("bool flag `%s' cannot have an argument",label))}
                set(name,"",0);continue
            }
            if !hasValue {
                if i+1>=len(args){return flagErr(fmt.Sprintf("expected argument for flag `%s'",label))}
                i++;value=args[i]
                if strings.HasPrefix(value,"-") && len(value)>1 {
                    numeric:=false
                    if kind=='i' {_,e:=strconv.ParseInt(value,0,64);numeric=e==nil}
                    if !numeric {return flagErr(fmt.Sprintf("expected argument for flag `%s', but got option `%s'",label,value))}
                }
            }
            n:=int64(0)
            if kind=='i' {
                var err error
                n,err=strconv.ParseInt(value,0,64)
                if err!=nil {return flagErr(fmt.Sprintf("invalid argument for flag `%s' (expected int): %s",label,err))}
            }
            set(name,value,int(n));hasValue=false
        }
    }
    if o.Layout!="" && !validLayout(o.Layout) {return o,fmt.Errorf("failed to parse command line options: invalid command line arguments: unknown layout: '%s'",o.Layout)}
    return o,nil
}
func validLayout(s string) bool {return s=="top-down"||s=="bottom-up"||s=="top-down-query-bottom"}
func parseHeight(s string) (n int,percent bool,err error) {
    if s=="" {return}
    v:=s
    if strings.HasSuffix(v,"%") {percent=true;v=v[:len(v)-1]}
    n,e:=strconv.Atoi(v)
    if e!=nil {return 0,percent,fmt.Errorf("invalid height specification: %q",s)}
    if n<=0 {
        if percent {err=fmt.Errorf("height percentage must be positive: %q",s)} else {err=fmt.Errorf("height must be positive: %q",s)}
    } else if percent && n>100 {err=fmt.Errorf("height percentage must not exceed 100: %q",s)}
    return
}
EOF
cat > config/config.go <<'EOF'
package config

import (
    "encoding/json"
    "fmt"
    "os"
    "path/filepath"
    "strings"
)

type OnCancelBehavior string

type Style []string
func (s *Style) UnmarshalJSON(b []byte) error {
    var v []string
    if err:=json.Unmarshal(b,&v);err!=nil {return fmt.Errorf("failed to unmarshal Style: %w",err)}
    *s=v;return nil
}
type Styles struct {
    Basic, SavedSelection, Selected, Query, QueryCursor, Matched, Prompt, Context Style
}
type ExternalFilter struct {
    Cmd string
    Args []string
    BufferThreshold int
}
type Config struct {
    Prompt string
    InitialFilter string
    FuzzyLongestSort bool
    StickySelection bool
    SuppressStatusMsg bool
    OnCancel OnCancelBehavior
    MaxScanBufferSize int
    ANSI bool
    Height string
    Layout string
    SelectionPrefix string
    Keymap map[string]string
    Action map[string][]string
    Style Styles
    CustomFilter map[string]ExternalFilter
    SingleKeyJump struct { ShowPrefix bool }
}
func Defaults() Config {
    c:=Config{Prompt:"QUERY>",InitialFilter:"IgnoreCase",MaxScanBufferSize:256,Layout:"top-down",OnCancel:"success"}
    c.Style.Basic=Style{"default","on_default"}
    c.Style.Selected=Style{"underline","on_magenta"}
    c.Style.SavedSelection=Style{"bold","black","on_cyan"}
    c.Style.QueryCursor=Style{"reverse"}
    c.Style.Matched=Style{"cyan"}
    c.Style.Context=Style{"bold"}
    return c
}
func ValidateOnCancel(s string) error {
    if s!="" && s!="success" && s!="error" {return fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"",s)}
    return nil
}
func FindFile() string {
    dirs:=[]string{}
    if s:=os.Getenv("XDG_CONFIG_HOME");s!="" {dirs=append(dirs,s)}
    home:=os.Getenv("HOME")
    if home!="" {dirs=append(dirs,filepath.Join(home,".config"))}
    if s:=os.Getenv("XDG_CONFIG_DIRS");s!="" {dirs=append(dirs,filepath.SplitList(s)...)}
    for _,d:=range dirs {
        for _,ext:=range []string{"json","yaml","yml"} {
            p:=filepath.Join(d,"peco","config."+ext)
            if st,e:=os.Stat(p);e==nil && !st.IsDir(){return p}
        }
    }
    if home!="" {
        for _,ext:=range []string{"json","yaml","yml"} {
            p:=filepath.Join(home,".peco","config."+ext)
            if st,e:=os.Stat(p);e==nil && !st.IsDir(){return p}
        }
    }
    return ""
}
func Load(path string) (Config,error) {
    c:=Defaults()
    if path=="" {path=FindFile()}
    if path=="" {return c,nil}
    f,e:=os.Open(path)
    if e!=nil {return c,fmt.Errorf("failed to open file %s: %w",path,e)}
    defer f.Close()
    ext:=strings.ToLower(filepath.Ext(path))
    kind:="JSON"
    if ext==".yaml"||ext==".yml" {
        kind="YAML"
        e=decodeYAML(f,&c)
    } else {e=json.NewDecoder(f).Decode(&c)}
    if e!=nil {return c,fmt.Errorf("failed to decode %s: %w",kind,e)}
    if e=ValidateOnCancel(string(c.OnCancel));e!=nil {return c,fmt.Errorf("failed to decode %s: %w",kind,e)}
    if c.Layout!="top-down" && c.Layout!="bottom-up" && c.Layout!="top-down-query-bottom" {return c,fmt.Errorf("invalid layout type: %s",c.Layout)}
    if c.InitialFilter=="" {c.InitialFilter="IgnoreCase"}
    return c,nil
}
EOF
