type sourceEvent struct { lines []*line; done bool }

// Terminal control codes do not belong to the searchable display text. The
// raw bytes are retained independently, so output is lossless (including NUL).
func makeLine(raw string,id int,nul bool) *line {
    display,out:=raw,raw
    if nul {if p:=strings.IndexByte(raw,0);p>=0{display=raw[:p];out=raw[p+1:]}}
    text,attrs:=plainANSI(display)
    return &line{id:id,raw:raw,text:text,output:out,runes:[]rune(text),ansi:attrs}
}
func plainANSI(s string)(string,[]style) {
    var b strings.Builder
    attrs:=[]style{};cur:=style{}
    for i:=0;i<len(s); {
        if s[i]==27 {
            if i+1<len(s)&&s[i+1]=='[' {
                j:=i+2;for j<len(s) && !(s[j]>=0x40&&s[j]<=0x7e){j++}
                if j<len(s) {if s[j]=='m' {cur=applySGR(cur,s[i+2:j])};i=j+1;continue}
            }
            if i+1<len(s)&&s[i+1]==']' {
                j:=i+2;for j<len(s)&&s[j]!=7 && !(s[j]==27&&j+1<len(s)&&s[j+1]=='\\'){j++}
                if j<len(s) {if s[j]==27{j++};i=j+1;continue}
            }
            i++;continue
        }
        r,n:=utf8.DecodeRuneInString(s[i:]);i+=n
        b.WriteRune(r);attrs=append(attrs,cur)
    }
    return b.String(),attrs
}
func scanSource(r io.Reader,maxKB int,nul bool,ch chan<-sourceEvent) {
    scan:=bufio.NewScanner(r)
    if maxKB<=0 {maxKB=256}
    max:=maxKB*1024
    scan.Buffer(make([]byte,min(4096,max)),max)
    batch:=[]*line{};id:=0
    for scan.Scan() {
        batch=append(batch,makeLine(scan.Text(),id,nul));id++
        if len(batch)>=100 {ch<-sourceEvent{lines:batch};batch=nil}
    }
    ch<-sourceEvent{lines:batch,done:true}
}
