    "os"
    "os/signal"
    "syscall"
    "time"

    "local/linefilter/config"
)
func errorExit(message string)int{fmt.Fprintln(os.Stderr,"Error: "+message);return 1}
func main(){os.Exit(run())}
func run() int {
    o,e:=parseOptions(os.Args[1:])
