    a,e:=newApp(o,c)
    if e!=nil{return errorExit("failed to setup peco: failed to apply configuration: "+e.Error())}
    var input io.Reader=os.Stdin
    if len(o.Files)>0 {
        f,err:=os.Open(o.Files[0])
        if err!=nil{return errorExit("failed to setup input source: failed to open file for input: "+err.Error())}
        defer f.Close();input=f
    } else if isTTY(os.Stdin){return errorExit("failed to setup input source: you must supply something to work with via filename or stdin")}
    events:=make(chan sourceEvent,1024)
    go scanSource(input,c.MaxScanBufferSize,o.Null,events)
    // A finite source can be answered without a screen in the automatic modes.
    initial:=time.NewTimer(5*time.Millisecond)
initialRead:
    for {
        select {
        case ev:=<-events:a.receive(ev);if ev.done{break initialRead}
        case <-initial.C:break initialRead
        }
    }
    initial.Stop()
    if a.sourceDone {
        if o.Exit0&&len(a.source)==0{return 1}
        if (o.Select1&&len(a.source)==1)||(o.SelectAll&&o.Query=="") {
            a.view=append([]result(nil),a.source...);a.clampIndex()
            if o.SelectAll {for _,r:=range a.view{a.saved[r.line.id]=r.line}}
            os.Stdout.Write(a.selectionData(true));return 0
        }
    }
    t,e:=openTerminal(a.height>0)
    if e!=nil{return errorExit("failed to initialize screen: "+e.Error())}
    a.term=t
    defer func(){_,_,off,_:=a.geometry();t.close(off)}()
    a.recalculate(false)
    if !a.sourceDone&&len(a.source)==0{a.status="Waiting for input...";a.statusUntil=time.Time{}}
    a.autoSelect()
    if a.finished{os.Stdout.Write(a.output);return a.exitCode}
    a.render()
    keyBytes:=make(chan []byte,128)
    go func(){b:=make([]byte,4096);for {n,e:=t.file.Read(b);if n>0{keyBytes<-append([]byte(nil),b[:n]...)};if e!=nil{close(keyBytes);return}}}()
    signals:=make(chan os.Signal,4)
    signal.Notify(signals,syscall.SIGWINCH,syscall.SIGTERM,syscall.SIGHUP,syscall.SIGINT)
    defer signal.Stop(signals)
    ticker:=time.NewTicker(10*time.Millisecond);defer ticker.Stop()
    decoder:=keyDecoder{}
    for !a.finished {
        changedSource:=false
        select {
        case ev:=<-events:
            a.receive(ev);changedSource=true
        drain:
            for {select {case ev:=<-events:a.receive(ev);default:break drain}}
        case b,ok:=<-keyBytes:
            if !ok{a.cancel();break};decoder.feed(b)
        case s:=<-signals:
            if s==syscall.SIGWINCH{t.size();t.last=nil;a.dirty=true}else{a.cancel()}
        case <-ticker.C:
        }
        if changedSource {
            if a.sourceDone&&o.Exit0&&len(a.source)==0{a.finished=true;a.exitCode=1;break}
            a.recalculate(false);a.autoSelect()
        }
        now:=time.Now()
        for !a.finished {
            k,ok:=decoder.next(now);if !ok{break}
            a.handleKey(k)
        }
        if a.finished{break}
        if !a.filterDue.IsZero()&&!now.Before(a.filterDue){a.recalculate(true);a.autoSelect()}
        if !a.statusUntil.IsZero()&&!now.Before(a.statusUntil){a.status="";a.statusUntil=time.Time{};a.dirty=true}
        if a.dirty&&!a.finished{a.render()}
    }
    // Restore the terminal before writing the selected records.
    _,_,off,_:=a.geometry();t.close(off)
    os.Stdout.Write(a.output)
    return a.exitCode
}
