package main

import (
    "unicode"
)

func copySelections(m map[int]*line)map[int]*line {r:=map[int]*line{};for k,v:=range m{r[k]=v};return r}
func (a *app) current() *result {if a.index<0||a.index>=len(a.view){return nil};return &a.view[a.index]}
func (a *app) toggleSelection() {r:=a.current();if r==nil||r.context{return};id:=r.line.id;if _,ok:=a.saved[id];ok{delete(a.saved,id)}else{a.saved[id]=r.line}}
func (a *app) updateRange() {
    if a.rangeStart<0{return}
    a.saved=copySelections(a.rangeSaved)
    first,last:=a.rangeStart,a.index
    if first>last {first,last=last,first+1}
    for i:=first;i<last&&i<len(a.view);i++{if i>=0&&!a.view[i].context{a.saved[a.view[i].line.id]=a.view[i].line}}
}
func (a *app) cancelRange() {if a.rangeStart>=0 {a.saved=copySelections(a.rangeSaved);a.rangeStart=-1;a.dirty=true}}
func (a *app) move(delta int) {
    n:=len(a.view);if n==0{return}
    if a.config.Layout=="bottom-up"{delta=-delta}
    a.index+=delta
    if a.index<0{a.index=n-1};if a.index>=n{a.index=0}
    a.updateRange();a.dirty=true
}
func (a *app) movePage(delta int) {
    if len(a.view)==0{return}
    _,_,_,page:=a.geometry()
    if a.config.Layout=="bottom-up"{delta=-delta}
    if delta>0 {
        if a.index/page>=(len(a.view)-1)/page{a.index=0}else{a.index=min(a.index+page,len(a.view)-1)}
    } else {
        if a.index/page==0{a.index=len(a.view)-1}else{a.index=max(0,a.index-page)}
    }
    a.updateRange();a.dirty=true
}
func (a *app) backwardWord()int {
    p:=a.caret
    for p>0&&unicode.IsSpace(a.query[p-1]){p--}
    for p>0&&!unicode.IsSpace(a.query[p-1]){p--}
    return p
}
func (a *app) forwardWord()int {
    p:=a.caret
    for p<len(a.query)&&unicode.IsSpace(a.query[p]){p++}
    for p<len(a.query)&&!unicode.IsSpace(a.query[p]){p++}
    return p
}
func (a *app) action(name string) {
    a.dirty=true
    switch name {
    case "ForwardChar":a.caret=min(a.caret+1,len(a.query))
    case "BackwardChar":a.caret=max(0,a.caret-1)
    case "BeginningOfLine":a.caret=0
    case "EndOfLine":a.caret=len(a.query)
    case "BackwardWord":a.caret=a.backwardWord()
    case "ForwardWord":a.caret=a.forwardWord()
    case "EndOfFile":
        if len(a.query)==0{a.cancel()}else{a.action("DeleteForwardChar")}
    case "DeleteForwardChar":
        if a.caret<len(a.query){a.query=append(a.query[:a.caret],a.query[a.caret+1:]...);a.queryChanged()}
    case "DeleteBackwardChar":
        if a.caret>0 {a.query=append(a.query[:a.caret-1],a.query[a.caret:]...);a.caret--;a.queryChanged()}
    case "DeleteForwardWord":
        p:=a.forwardWord();if p!=a.caret{a.query=append(a.query[:a.caret],a.query[p:]...);a.queryChanged()}
    case "DeleteBackwardWord":
        p:=a.backwardWord();if p!=a.caret{a.query=append(a.query[:p],a.query[a.caret:]...);a.caret=p;a.queryChanged()}
    case "KillBeginningOfLine":
        if a.caret>0 {a.query=append([]rune(nil),a.query[a.caret:]...);a.caret=0;a.queryChanged()}
    case "KillEndOfLine":
        if a.caret<len(a.query){a.query=a.query[:a.caret];a.queryChanged()}
    case "DeleteAll":
        a.query=nil;a.caret=0;a.queryChanged()
    case "SelectUp","SelectPrevious":a.move(-1)
    case "SelectDown","SelectNext":a.move(1)
    case "ScrollPageUp","SelectPreviousPage":a.movePage(-1)
    case "ScrollPageDown","SelectNextPage":a.movePage(1)
    case "ScrollFirstItem":
        a.index=0;if a.config.Layout=="bottom-up"{a.index=max(0,len(a.view)-1)};a.updateRange()
    case "ScrollLastItem":
        a.index=max(0,len(a.view)-1);if a.config.Layout=="bottom-up"{a.index=0};a.updateRange()
    case "ScrollLeft":
        w,_,_,_:=a.geometry();a.scroll=max(0,a.scroll-w/2)
    case "ScrollRight":
        w,_,_,_:=a.geometry();maxWidth:=0
        for _,r:=range a.view{maxWidth=max(maxWidth,textWidth(r.line.text))}
        a.scroll=min(max(0,maxWidth-w),a.scroll+w/2)
    case "ToggleSelection":a.toggleSelection()
    case "ToggleSelectionAndSelectNext":a.toggleSelection();a.move(1)
    case "SelectAll","SelectVisible":
        first,last:=0,len(a.view)
        if name=="SelectVisible"{_,_,_,page:=a.geometry();first=a.index/page*page;last=min(first+page,len(a.view))}
        for _,r:=range a.view[first:last]{if !r.context{a.saved[r.line.id]=r.line}}
    case "SelectNone":a.saved=map[int]*line{}
    case "InvertSelection":
        for _,r:=range a.view {if r.context{continue};if _,ok:=a.saved[r.line.id];ok{delete(a.saved,r.line.id)}else{a.saved[r.line.id]=r.line}}
    case "ToggleRangeMode","ToggleSelectMode":
        if a.rangeStart>=0 {a.rangeStart=-1}else{a.rangeStart=a.index;a.rangeSaved=copySelections(a.saved)}
    case "CancelRangeMode","CancelSelectMode":a.cancelRange()
    case "ToggleSingleKeyJump":a.singleJump=!a.singleJump
    case "GoToNextSelection","GoToPreviousSelection":
        n:=len(a.view)
        step:=1;if name=="GoToPreviousSelection"{step=-1}
        for i:=1;i<=n;i++ {idx:=(a.index+i*step+n)%n;if _,ok:=a.saved[a.view[idx].line.id];ok{a.index=idx;break}}
    case "RotateFilter":
        a.filterIndex=(a.filterIndex+1)%len(a.filters)
        if len(a.query)>0{a.queryChanged()}
    case "BackToInitialFilter":
        a.filterIndex=0;if len(a.query)>0{a.queryChanged()}
    case "RefreshScreen":
        a.recalculate(true);if a.term!=nil{a.term.last=nil}
    case "ToggleQuery":
        a.query,a.alternateQuery=a.alternateQuery,a.query
        a.caret=min(a.caret,len(a.query));a.recalculate(true)
    case "ViewAround":
        a.alternateQuery=a.query;a.query=nil;a.caret=0;a.index=0;a.recalculate(true)
    case "FreezeResults":
        a.frozen=append([]result(nil),a.view...);a.hasFrozen=true
        a.query=nil;a.caret=0;a.zoomed=false;a.zoomOriginal=nil
        a.setStatus("Results frozen")
    case "UnfreezeResults":
        if !a.hasFrozen{a.setStatus("No frozen results");break}
        a.frozen=nil;a.hasFrozen=false;a.query=nil;a.caret=0;a.index=0;a.recalculate(true);a.setStatus("Results unfrozen")
    case "ZoomIn":a.zoomIn()
    case "ZoomOut":
        if !a.zoomed{break}
        a.view=a.zoomOriginal;a.zoomed=false;a.index=a.zoomIndex;a.clampIndex();a.zoomOriginal=nil
    case "Finish":a.finish()
    case "Cancel":a.cancel()
    }
}
func (a *app) zoomIn() {
    if a.zoomed{a.setStatus("Already zoomed in");return}
    if len(a.query)==0{return}
    a.zoomOriginal=append([]result(nil),a.view...);a.zoomIndex=a.index
    original:=a.source
    positions:=map[int]int{}
    for i,r:=range original{positions[r.line.id]=i}
    matched:=map[int]result{};include:=map[int]bool{}
    for _,r:=range a.view {
        pos,ok:=positions[r.line.id];if !ok{continue}
        matched[pos]=r
        for i:=max(0,pos-3);i<=min(len(original)-1,pos+3);i++{include[i]=true}
    }
    currentID:=-1;if c:=a.current();c!=nil{currentID=c.line.id}
    view:=[]result{}
    for i,r:=range original {
        if !include[i]{continue}
        if m,ok:=matched[i];ok{view=append(view,m)}else{view=append(view,result{line:r.line,context:true})}
        if r.line.id==currentID{a.index=len(view)-1}
    }
    a.view=view;a.zoomed=true;a.clampIndex()
}
