package main

import (
    "math"
    "os"
    "strings"
)

type labColor struct{ l,a,b float64 }
func colorLab(rgb int)labColor {
    component:=func(v int)float64 {x:=float64(v)/255;if x<=.04045{return x/12.92};return math.Pow((x+.055)/1.055,2.4)}
    r,g,b:=component(rgb>>16&255),component(rgb>>8&255),component(rgb&255)
    x:=(.4124564*r+.3575761*g+.1804375*b)/.95047
    y:=.2126729*r+.7151522*g+.0721750*b
    z:=(.0193339*r+.1191920*g+.9503041*b)/1.08883
    f:=func(v float64)float64{if v>.008856451679{return math.Cbrt(v)};return 7.787037037*v+16.0/116}
    x,y,z=f(x),f(y),f(z)
    return labColor{116*y-16,500*(x-y),200*(y-z)}
}
var rgbPalette [256]int
var labPalette [256]labColor
var colorCache=map[[2]int]int{}
func init() {
    base:=[]int{0x000000,0x800000,0x008000,0x808000,0x000080,0x800080,0x008080,0xc0c0c0,0x808080,0xff0000,0x00ff00,0xffff00,0x0000ff,0xff00ff,0x00ffff,0xffffff}
    copy(rgbPalette[:],base)
    levels:=[]int{0,95,135,175,215,255}
    for i:=16;i<232;i++ {n:=i-16;rgbPalette[i]=levels[n/36]<<16|levels[n/6%6]<<8|levels[n%6]}
    for i:=232;i<256;i++ {v:=8+(i-232)*10;rgbPalette[i]=v<<16|v<<8|v}
    for i,c:=range rgbPalette{labPalette[i]=colorLab(c)}
}
func terminalColors()int {
    if os.Getenv("TCELL_TRUECOLOR")!="disable" {
        ct:=strings.ToLower(os.Getenv("COLORTERM"))
        if ct=="truecolor"||ct=="24bit"||strings.HasSuffix(os.Getenv("TERM"),"-direct"){return 1<<24}
    }
    term:=os.Getenv("TERM")
    if strings.HasPrefix(term,"vt"){return 0}
    if strings.Contains(term,"256"){return 256}
    if strings.Contains(term,"16color"){return 16}
    return 8
}
func limitColor(c,cap int)int {
    if c==0||cap==0{return 0}
    if cap>=1<<24{return c}
    if c<=cap{return c}
    key:=[2]int{c,cap};if v,ok:=colorCache[key];ok{return v}
    rgb:=c&0xffffff
    if c&0x1000000==0 {if c<1||c>256{return 0};rgb=rgbPalette[c-1]}
    target:=colorLab(rgb);best:=0;distance:=math.MaxFloat64
    for i:=0;i<cap;i++ {
        p:=labPalette[i]
        d:=(p.l-target.l)*(p.l-target.l)+(p.a-target.a)*(p.a-target.a)+(p.b-target.b)*(p.b-target.b)
        if d<distance {best=i;distance=d}
    }
    colorCache[key]=best+1;return best+1
}
