    src:=testSource("alpha","Alpha","ALPHA","beta alpha","alpha beta","-foo","foo-bar","foo bar","bar foo","aXlXpXhXa")
    cases:=[]struct{name,q string;want []string}{
        {"IgnoreCase","alpha",[]string{"alpha","Alpha","ALPHA","beta alpha","alpha beta"}},
        {"CaseSensitive","Alpha",[]string{"Alpha"}},
        {"SmartCase","Alpha",[]string{"Alpha"}},
        {"SmartCase","al be",[]string{"beta alpha","alpha beta"}},
        {"IRegexp","^a.*a$",[]string{"alpha","Alpha","ALPHA","alpha beta","aXlXpXhXa"}},
        {"Regexp","^a.*a$",[]string{"alpha","alpha beta","aXlXpXhXa"}},
        {"Regexp","[",[]string{}},
        {"IgnoreCase","foo -bar",[]string{"-foo"}},
        {"IgnoreCase",`\-foo`,[]string{"-foo"}},
        {"Fuzzy","al be",[]string{"alpha beta"}},
        {"Fuzzy","Alpha",[]string{"Alpha"}},
        {"Fuzzy","foo -Bar",[]string{"-foo"}},
    }
    c:=config.Defaults()
    for _,tc:=range cases{t.Run(tc.name+"/"+tc.q,func(t *testing.T){got:=texts(runFilter(src,tc.q,tc.name,&c));if !reflect.DeepEqual(got,tc.want){t.Fatalf("got %q, want %q",got,tc.want)}})}
}
func TestQuerySeparatorsAndUnicode(t *testing.T) {
