    a.query=[]rune("t");a.caret=1;a.recalculate(true);a.action("FreezeResults")
    if len(a.view)!=2||len(a.query)!=0{t.Fatal(texts(a.view),string(a.query))}
    a.query=[]rune("hr");a.caret=2;a.recalculate(true)
    if len(a.view)!=1||a.view[0].line.text!="three"{t.Fatal(texts(a.view))}
    a.action("UnfreezeResults");if len(a.view)!=5||len(a.query)!=0{t.Fatal(texts(a.view))}
}
